/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */

const states = new WeakMap()

function validateEvent(event) {
  if (event === null || typeof event !== 'object') throw new Error('event must be an object')
  if (event.type !== 'debit' && event.type !== 'credit') throw new Error('invalid event type')
  if (typeof event.account !== 'string' || event.account.length === 0) throw new Error('account must be a non-empty string')
  if (!Number.isSafeInteger(event.amountCents) || event.amountCents <= 0) {
    throw new Error('amount must be a positive integer')
  }
}

function record(state, event) {
  const stored = Object.freeze({ ...event, seq: state.events.length })
  state.events.push(stored)
  const current = state.balances.get(stored.account) ?? 0
  state.balances.set(stored.account, current + (stored.type === 'credit' ? stored.amountCents : -stored.amountCents))
}

function assertCanDebit(state, account, amountCents) {
  if ((state.balances.get(account) ?? 0) < amountCents) throw new Error('insufficient funds')
}

export function createLedger() {
  const state = { events: [], balances: new Map() }

  const ledger = {
    append(event) {
      validateEvent(event)
      if (event.type === 'debit') assertCanDebit(state, event.account, event.amountCents)
      record(state, event)
    },
    eventCount() {
      return state.events.length
    },
    fold() {
      return Object.fromEntries(state.balances)
    },
    events() {
      return state.events.map((event) => ({ ...event }))
    },
  }

  states.set(ledger, state)
  return ledger
}

/**
 * Commit both sides of a transfer as one ledger operation. This is deliberately
 * not part of the package's public API; transfer() is the supported entry point.
 */
export function appendTransfer(ledger, debit, credit) {
  const state = states.get(ledger)
  if (state === undefined) throw new Error('invalid ledger')

  validateEvent(debit)
  validateEvent(credit)
  if (debit.type !== 'debit' || credit.type !== 'credit') throw new Error('invalid transfer events')
  if (debit.amountCents !== credit.amountCents) throw new Error('transfer amounts must match')
  assertCanDebit(state, debit.account, debit.amountCents)

  record(state, debit)
  record(state, credit)
}

/**
 * Balance snapshot cache. Each ledger has an independent cache. Reads replay
 * events added since the last snapshot so they always reflect the current
 * stream; a full fold periodically replaces the incrementally updated cache.
 */
const REFRESH_EVERY = 8

let caches = new WeakMap()

function applyEvent(balances, event) {
  const current = balances[event.account] ?? 0
  balances[event.account] = current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
}

export function getBalance(ledger, account) {
  const eventCount = ledger.eventCount()
  let cache = caches.get(ledger)

  // Rebuild if this ledger has no snapshot, if enough events have accumulated,
  // or if the stream was unexpectedly replaced/truncated.
  if (cache === undefined || eventCount < cache.atCount || eventCount >= cache.fullFoldAt + REFRESH_EVERY) {
    cache = { atCount: eventCount, fullFoldAt: eventCount, balances: ledger.fold() }
    caches.set(ledger, cache)
  } else if (eventCount > cache.atCount) {
    const events = ledger.events()
    for (let index = cache.atCount; index < eventCount; index += 1) applyEvent(cache.balances, events[index])
    cache.atCount = eventCount
  }

  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

import { appendTransfer } from './ledger.js'
import { getBalance } from './snapshot.js'

/**
 * Transfer money between two accounts. Validates the sender's balance, appends
 * a DEBIT then a CREDIT atomically, and finally notifies hooks.onSettled. The
 * settled notification runs after the ledger has been updated.
 */
export function transfer(ledger, from, to, amountCents, hooks = {}) {
  if (!Number.isSafeInteger(amountCents) || amountCents <= 0) throw new Error('amount must be positive')
  const balance = getBalance(ledger, from)
  if (balance < amountCents) throw new Error('insufficient funds')

  const ts = hooks.clock?.() ?? Date.now()
  const debitId = hooks.nextId?.() ?? `evt-${ledger.eventCount()}`
  const creditId = hooks.nextId?.() ?? `evt-${ledger.eventCount() + 1}`

  appendTransfer(
    ledger,
    { type: 'debit', account: from, amountCents, ts, id: debitId },
    { type: 'credit', account: to, amountCents, ts, id: creditId },
  )

  hooks.onSettled?.({ from, to, amountCents, ts })
  return true
}

