import { transfer } from './transfer.js'

/**
 * Rebate hook factory. After a transfer settles, a fixed-percentage rebate is
 * paid back to the sender. The rebate is itself an ordinary transfer, so it
 * triggers the hook again until the rebate rounds down to zero.
 */
export function createRebateHook(ledger, ratePercent) {
  if (!Number.isFinite(ratePercent) || ratePercent < 0 || ratePercent >= 100) {
    throw new Error('rebate rate must be between 0 and 100')
  }

  const pending = []
  let processing = false

  function hook(payload) {
    pending.push(payload)
    if (processing) return

    processing = true
    try {
      while (pending.length > 0) {
        const { from, to, amountCents } = pending.shift()
        const rebate = Math.min(amountCents - 1, Math.floor((amountCents * ratePercent) / 100))
        if (rebate > 0) transfer(ledger, to, from, rebate, { onSettled: hook })
      }
    } finally {
      processing = false
    }
  }

  return hook
}
